<script>
 import RegionState from './RegionState.svelte';import {refreshTaskList} from '../services/task-monitor.js';
 import {onMount} from 'svelte';import Composer from './Composer.svelte';import ErrorCard from './ErrorCard.svelte';import Button from '../ui/Button.svelte';import {chat,sendChat,connectChat} from '../stores/chat.svelte';import {selection} from '../stores/selection.svelte';import {project} from '../stores/project.svelte';import {tasks} from '../stores/tasks.svelte';import {assets} from '../stores/assets.svelte';import {shell,saveShell,navigate} from '../app/shell.svelte';import {libraryUrl} from '../lib/router.ts';import {homeContext} from '../lib/home.ts';
 const commands=[['白底主图','/白底'],['批量抠图','/抠图'],['统一比例','/比例 4:5'],['生成场景图','生成简洁高级的北欧静物产品场景图，Sony A7R III 摄影风格，保留产品结构、材质、颜色和文字']];
 const recent=$derived([...project.items].sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0)).slice(0,4)),recentTasks=$derived(Object.values(tasks.byId).sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0)).slice(0,4));
 const labels={running:'处理中',queued:'排队中',done:'已完成',partial:'部分完成',failed:'失败',cancelled:'已取消',waiting:'等待异步结果'};
 onMount(connectChat);
 async function send(value=chat.draft,operations=null){const context=homeContext(value,{assets:project.items.find(p=>p.id===project.currentId)?.assets||[],mentions:selection.mentions,selected:selection.selectedIds,filter:assets.filter});if(!project.currentId||!context.resolvedTarget.ids.length){await sendChat(value,{context,operations});return;}selection.set(context.resolvedTarget.ids);shell.filter=context.filter;shell.chatCollapsed=false;saveShell();const pending=sendChat(value,{context,operations});navigate(libraryUrl(context.filter));await pending;}
 function openProject(id){project.select(id);shell.projectId=id;saveShell();navigate('/library');}
</script>
<section class="home-page" aria-label="首页"><div class="home-intro"><h1>今天要处理什么？</h1><p>选择项目里的图片，或拖入一组原图。</p></div><div class="home-input"><Composer onsend={send}/></div><div class="home-commands" role="group" aria-label="快捷指令">{#each commands as [label,text]}<Button title={label} onclick={()=>{chat.draft=text;void send(text,label==='生成场景图'?[{kind:'generate',prompt:text,ratio:'1:1',orientation:'landscape',resolution:'1K'}]:null);}}>{label}</Button>{/each}</div>{#if chat.error}<ErrorCard message={chat.error} onretry={()=>send()} onskip={()=>chat.error=''}/>{/if}
 <div class="home-recent"><section><h2>最近项目</h2>{#if recent.length}<div class="home-projects">{#each recent as item}<button onclick={()=>openProject(item.id)}><span>{item.name}</span><small>{item.assets.filter(asset=>!asset.trashed).length} 张图片</small></button>{/each}</div>{:else}<p>拖入图片后自动建立项目。</p>{/if}</section><section><h2>最近任务</h2>{#if tasks.error}<RegionState compact state="error" title="无法更新最近任务" message={tasks.error} onretry={()=>refreshTaskList().catch(()=>{})}/>{:else if tasks.status==='idle'||tasks.status==='loading'}<RegionState compact state="loading" title="正在读取任务"/>{/if}{#if recentTasks.length}{#each recentTasks as task}<button class="home-task" onclick={()=>{if(task.projectId)project.select(task.projectId);selection.set(task.resultAssetIds||[]);shell.chatCollapsed=false;saveShell();navigate('/library');}}><span>{labels[task.state]||task.state}</span><small>{task.done||0} / {task.total||0}</small></button>{/each}{:else if tasks.status==='ready'&&!tasks.error}<p>处理完成的任务会保留在这里。</p>{/if}</section></div>
</section>
<style>.home-page{box-sizing:border-box;max-width:784px;margin:0 auto;padding:clamp(48px,10vh,112px) 32px 48px;color:var(--text);font:13px system-ui,sans-serif}.home-intro{margin-bottom:24px}.home-intro h1{font-size:20px;line-height:1.4;font-weight:600;margin:0 0 12px}.home-intro p{color:var(--text-dim);line-height:1.8;margin:0}.home-input{border:1px solid var(--border);border-radius:8px;overflow:visible;background:var(--bg-elev)}.home-input :global(.composer){border:0;border-radius:8px}.home-commands{display:flex;flex-wrap:wrap;gap:8px;margin:16px 0 40px}.home-recent{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,1fr);gap:32px}.home-recent h2{font-size:14px;font-weight:600;margin:0 0 16px}.home-recent p{font-size:12px;color:var(--text-dim);line-height:1.8;margin:0}.home-projects{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.home-recent button{font:13px system-ui,sans-serif;display:flex;flex-direction:column;align-items:flex-start;gap:8px;min-width:0;text-align:left;background:var(--bg-elev);color:var(--text);border:1px solid var(--border);border-radius:8px;padding:12px;cursor:pointer}.home-recent button>span{max-width:100%;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.home-recent small{font-size:12px;color:var(--text-dim)}.home-recent button:hover{border-color:var(--accent)}.home-recent button:active{background:var(--accent-soft)}.home-recent button:focus-visible{outline:2px solid var(--focus);outline-offset:2px}.home-recent .home-task{flex-direction:row;align-items:center;justify-content:space-between;width:100%;border-width:0 0 1px;border-radius:0;background:transparent}</style>
